# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: "Full Zed-like" look: title bar, left dock, tab bar, one continuous
#          editor buffer with a line-number gutter and inline outputs, status bar.
# ---------------------------------------------------------------------------
from __future__ import annotations

import reflex as rx

from ..sample import CELLS, MODES, SCHEMA, VARIABLES
from .common import code_block, html_table, switcher


def _output(output: dict | None) -> rx.Component | None:
    if output is None:
        return None
    if output["kind"] == "table":
        body = html_table(output["columns"], output["rows"])
    elif output["kind"] == "reply":
        body = rx.el.div(
            rx.el.p(output["paragraph"]),
            rx.el.ul(*[rx.el.li(b) for b in output["bullets"]]),
            class_name="reply sans",
        )
    else:
        body = rx.el.pre(output["text"])
    return rx.el.div(body, class_name="inline-output")


def _cells() -> list[rx.Component]:
    blocks: list[rx.Component] = []
    line = 1
    for cell in CELLS:
        focused = cell.get("focused", False)
        blocks.append(
            rx.el.div(
                rx.el.div(
                    code_block(cell["code"], start=line, cursor=focused),
                    rx.el.span(
                        rx.el.span(MODES[cell["mode"]]["icon"], class_name="mono"),
                        f" {MODES[cell['mode']]['label']}",
                        class_name="chip sans",
                    ),
                    class_name="input",
                ),
                _output(cell["output"]),
                class_name=f"zcell m-{cell['mode']}" + (" is-focused" if focused else ""),
            )
        )
        line += len(cell["code"])
    return blocks


def _dock() -> rx.Component:
    return rx.el.div(
        rx.el.div("Variables", class_name="dock-title"),
        *[
            rx.el.div(rx.el.span(name, class_name="mono"), rx.el.span(kind, class_name="dim"), class_name="dock-row")
            for name, kind in VARIABLES
        ],
        rx.el.div("Schema", class_name="dock-title"),
        *[
            rx.el.div(
                rx.el.div(
                    rx.el.span(rx.el.span(MODES["smash"]["icon"], class_name="mono accent-aqua"), f" {table}"),
                    class_name="dock-row",
                ),
                *[rx.el.div(column, class_name="dock-row is-child mono") for column in columns],
            )
            for table, columns in SCHEMA.items()
        ],
        class_name="dock",
    )


def zed_page() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.span("delulu-smash", class_name="title"),
            rx.el.span("main", class_name="dim"),
            rx.el.span(class_name="spacer"),
            rx.el.span(rx.el.span("●", class_name="accent-green"), " kernel idle", class_name="dim"),
            class_name="titlebar sans",
        ),
        rx.el.div(
            _dock(),
            rx.el.div(
                rx.el.div(
                    rx.el.span("notebook", rx.el.span("×", class_name="dim"), class_name="tab is-active"),
                    rx.el.span("scratch", rx.el.span("×", class_name="dim"), class_name="tab"),
                    class_name="tabbar sans",
                ),
                rx.el.div(*_cells(), class_name="zed-editor mono"),
                class_name="zed-center",
            ),
            class_name="zed-main",
        ),
        rx.el.div(
            rx.el.span("Variables", class_name="dim"),
            rx.el.span(class_name="spacer"),
            rx.el.span("Ln 9, Col 1", class_name="dim"),
            rx.el.span(rx.el.span(MODES["python"]["icon"], class_name="mono accent-green"), " python"),
            class_name="statusbar sans",
        ),
        switcher("zed"),
        class_name="page zed sans",
    )
